package it.replica8.castor.core.geometry.domain;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * The fixture file shared with the frontend (fixtures/coordinates.json at the repository root, regenerated by
 * scripts/generate-coordinate-fixtures.mjs). Tests run with the module directory as working directory.
 */
public final class CoordinateFixtures {

    private static final Path FILE =
            Path.of("..", "..", "fixtures", "coordinates.json").toAbsolutePath().normalize();

    public record Control(String name, LonLat lonLat, LocalPoint local) {}

    public record Rect(
            LonLat anchor, double heading, double length, double width, double rotation, List<LonLat> corners) {}

    public record Heading(double heading, double rotation) {}

    public final QuayFrame frame;
    public final double backendVsFrontendM;
    public final double roundTripM;
    public final double controlPointM;
    public final List<Control> controlPoints = new ArrayList<>();
    public final List<Control> points = new ArrayList<>();
    public final List<Rect> rectangles = new ArrayList<>();
    public final List<Heading> headings = new ArrayList<>();

    public CoordinateFixtures() {
        try {
            JsonNode root = new ObjectMapper().readTree(FILE.toFile());
            JsonNode f = root.get("frame");
            frame = new QuayFrame(
                    f.get("lon0").asDouble(),
                    f.get("lat0").asDouble(),
                    f.get("rotDeg").asDouble());
            JsonNode tol = root.get("tolerances");
            backendVsFrontendM = tol.get("backendVsFrontendM").asDouble();
            roundTripM = tol.get("roundTripM").asDouble();
            controlPointM = tol.get("controlPointM").asDouble();
            root.get("controlPoints").forEach(n -> controlPoints.add(control(n)));
            root.get("points").forEach(n -> points.add(control(n)));
            root.get("rectangles")
                    .forEach(n -> rectangles.add(new Rect(
                            lonLat(n.get("anchor")),
                            n.get("heading").asDouble(),
                            n.get("length").asDouble(),
                            n.get("width").asDouble(),
                            n.get("rotation").asDouble(),
                            toList(n.get("corners")))));
            root.get("headings")
                    .forEach(n -> headings.add(new Heading(
                            n.get("heading").asDouble(), n.get("rotation").asDouble())));
        } catch (IOException e) {
            throw new IllegalStateException("Cannot read " + FILE, e);
        }
    }

    private static Control control(JsonNode n) {
        return new Control(
                n.has("name") ? n.get("name").asText() : "point",
                new LonLat(n.get("lon").asDouble(), n.get("lat").asDouble()),
                new LocalPoint(n.get("x").asDouble(), n.get("y").asDouble()));
    }

    private static LonLat lonLat(JsonNode a) {
        return new LonLat(a.get(0).asDouble(), a.get(1).asDouble());
    }

    private static List<LonLat> toList(JsonNode a) {
        var out = new ArrayList<LonLat>();
        a.forEach(n -> out.add(lonLat(n)));
        return out;
    }

    /** Ground distance in metres between two WGS84 points close together, on the local degree scale. */
    public static double metresApart(LonLat a, LonLat b) {
        double lat = (a.lat() + b.lat()) / 2;
        return Math.hypot(
                (a.lon() - b.lon()) * QuayFrame.metresPerDegreeLon(lat),
                (a.lat() - b.lat()) * QuayFrame.metresPerDegreeLat(lat));
    }
}
